begin;
select pg_advisory_xact_lock(hashtext('geostats-v16.3.4-runtime-catalog'));
CREATE OR REPLACE FUNCTION public.category_recovery_ready_v16_3_4(p_id text)
returns boolean language sql stable security definer set search_path='' as $function$
select coalesce((select e.approved and e.rules_version='16.3.4'
 and e.snapshot_fingerprint=public.category_recovery_fingerprint_v16_3_4(e.category_id)
 and jsonb_array_length(e.proofs) between 1 and 3
 and (select count(distinct p->>'difficulty')=jsonb_array_length(e.proofs)
      and bool_and(coalesce((p->>'reachable')::boolean,false))
      from jsonb_array_elements(e.proofs) p where p->>'difficulty' in ('easy','normal','expert'))
 and coalesce(c.metadata->'playableDifficulties','["easy","normal","expert"]'::jsonb)
      @> (select jsonb_agg(p->>'difficulty') from jsonb_array_elements(e.proofs) p)
 and coalesce(c.metadata->'playableDifficulties','["easy","normal","expert"]'::jsonb)
      <@ (select jsonb_agg(p->>'difficulty') from jsonb_array_elements(e.proofs) p)
 and not exists(select 1 from jsonb_array_elements(e.proofs) p
 cross join lateral jsonb_array_elements_text(p->'witness'->'categories') partner
 left join public.stat_categories pc on pc.id=partner.value
 where pc.id is null or not coalesce(pc.metadata->'playableDifficulties','["easy","normal","expert"]'::jsonb) @> jsonb_build_array(p->>'difficulty'))
 and not exists(select 1 from jsonb_each_text(e.dependency_fingerprints) d
                where d.value is distinct from public.category_recovery_fingerprint_v16_3_4(d.key))
 from public.category_recovery_evidence_v16_3_4 e join public.stat_categories c on c.id=e.category_id
 where e.category_id=p_id),false)
$function$;
CREATE OR REPLACE FUNCTION public.assert_v16_3_4_runtime_catalog()
 RETURNS TABLE(release_ready_categories integer, enabled_categories integer, safe_but_hidden_categories integer, unsafe_published_categories integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare release_ready integer;
declare enabled_count integer;
declare hidden_count integer;
declare unsafe_count integer;
begin
  with reachability as (
    select category_id
    from public.generator_reachability_v16_2_7
    group by category_id
    having bool_or(reachable)
  )
  select
    count(*) filter(where v.computed_playable_v16_2 and r.category_id is not null)::integer,
    count(*) filter(where v.enabled and v.eligible_daily)::integer,
    count(*) filter(where v.computed_playable_v16_2 and r.category_id is not null and not (v.enabled and v.eligible_daily))::integer,
    count(*) filter(where (v.enabled or v.eligible_daily) and not (v.computed_playable_v16_2 and r.category_id is not null))::integer
  into release_ready,enabled_count,hidden_count,unsafe_count
  from public.category_runtime_review_v16_2 v
  left join reachability r on r.category_id=v.id;

  if hidden_count<>0 then
    raise exception 'v16.3.4 catalog guard found % safe but hidden categories',hidden_count;
  end if;
  if unsafe_count<>0 then
    raise exception 'v16.3.4 catalog guard found % unsafe published categories',unsafe_count;
  end if;
  if enabled_count<>release_ready then
    raise exception 'v16.3.4 release-ready and enabled catalogs differ: ready %, enabled %',release_ready,enabled_count;
  end if;

  return query select release_ready,enabled_count,hidden_count,unsafe_count;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.category_v16_3_4_should_publish(p_category_id text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((
    select v.computed_playable_v16_2
      and exists (
        select 1
        from public.generator_reachability_v16_2_7 g
        where g.category_id=v.id
        group by g.category_id
        having bool_or(g.reachable)
      )
    from public.category_runtime_review_v16_2 v
    where v.id=p_category_id
  ),false)
$function$
;
