    v.governance_version,
    v.duplicate_status,
    v.superseded_by,
    v.auto_decision_reason,
    v.curation_status,
    v.curation_reason,
    v.curation_version,
    v.credibility_score,
    v.credibility_status,
    v.credibility_reason,
    v.evidence_label,
    v.comparability_risk,
    v.corroboration_status,
    v.plain_language_description,
    v.technical_definition,
    v.unit_explanation,
    v.source_page_url,
    v.exact_query_url,
    v.download_url,
    v.api_url,
    v.dataset_release,
    v.retrieved_at,
    v.license_name,
    v.license_url,
    v.source_query,
    v.derivation_method,
    v.derivation_version,
    v.input_datasets,
    v.verifiability_score,
    v.verifiability_status,
    v.understandability_score,
    v.fun_score,
    v.objective_status,
    v.player_quality_status,
    v.player_quality_reason,
    v.validation_status,
    v.validation_version,
    v.validated_at,
    v.validation_reason,
    v.source_snapshot_checksum,
    v.stored_snapshot_checksum,
    v.validated_observation_count,
    v.validation_expected_count,
    v.validation_mismatch_count,
    v.validation_ranking_mismatch_count,
    v.semantic_family,
    v.semantic_topic,
    v.player_source_url,
    v.player_source_status,
    v.player_source_reason,
    v.player_source_checked_at,
    v.content_review_status,
    v.content_review_reason,
    v.content_review_version,
    v.immediate_comprehension_score,
    v.gameplay_interest_score,
    v.uniqueness_score,
    v.link_quality_score,
    v.editorial_status,
    v.political_self_reported,
    v.confusing,
    v.esoteric,
    v.subjective_or_composite,
    v.stale_data,
    v.poor_coverage,
    v.duplicate_of,
    v.recommended_title,
    v.semantic_group,
    v.editorial_notes,
    v.reviewed_by,
    v.reviewed_at,
    v.editorial_updated_at,
    v.effective_title,
    v.effective_semantic_group,
    v.hard_gate_ready,
    v.editorial_ready,
    v.computed_playable_v15,
    v.v15_blockers,
    v.source_link_ready,
    v.v15_warnings,
    v.ranking_completeness_status,
    v.ranking_completeness_reason,
    v.top_value_distinct_count,
    v.top_value_feasible,
    v.computed_playable_v16,
    v.v16_blockers,
    v.v16_warnings,
    v.semantic_audit_status,
    v.semantic_source_identity_status,
    v.semantic_title_unit_status,
    v.semantic_result_logic_status,
    v.semantic_audit_issues,
    v.semantic_audit_warnings,
    v.semantic_top_values,
    v.semantic_bottom_values,
    a.proposed_status AS promotion_decision_v16_2,
    a.reason AS promotion_reason_v16_2,
    a.primary_blocker AS primary_blocker_v16_2,
    a.blocker_class AS blocker_class_v16_2,
    a.strict_pass AS strict_pass_v16_2,
    a.source_quality_floor AS source_quality_floor_v16_2,
    a.suggested_duplicate_of AS suggested_duplicate_of_v16_2,
    a.proposed_status = 'playable'::text AND v.editorial_status = 'approved'::text AND a.strict_pass AND category_v16_2_6_hard_block_reason(c.id, c.source_organization, c.source_indicator_code, v.effective_title, c.metadata) IS NULL AND cardinality(legacy.blockers) = 0 AND (NOT EXISTS (SELECT 1 FROM public.category_recovery_evidence_v16_3_4 re WHERE re.category_id=v.id) OR public.category_recovery_ready_v16_3_4(v.id)) AS computed_playable_v16_2,
    array_remove(ARRAY[
        CASE
            WHEN a.proposed_status <> 'playable'::text THEN a.primary_blocker
            ELSE NULL::text
        END, category_v16_2_6_hard_block_reason(c.id, c.source_organization, c.source_indicator_code, v.effective_title, c.metadata),
        CASE
            WHEN cardinality(legacy.blockers) > 0 THEN 'legacy_rejection_reaudit'::text
            ELSE NULL::text
        END, CASE WHEN EXISTS (SELECT 1 FROM public.category_recovery_evidence_v16_3_4 re WHERE re.category_id=v.id) AND NOT public.category_recovery_ready_v16_3_4(v.id) THEN 'recovery_witness_stale'::text ELSE NULL::text END], NULL::text) AS v16_2_blockers,
    array_remove(ARRAY[
        CASE
            WHEN v.validation_status <> 'verified'::text AND NOT category_v15_true_integrity_failure(v.validation_status, v.validation_reason, v.validation_mismatch_count, v.validation_ranking_mismatch_count) THEN 'Official values are usable; non-data source metadata remain incomplete.'::text
            ELSE NULL::text
        END,
        CASE
            WHEN v.ranking_completeness_status = 'top_end_complete'::text THEN 'Ranking is top-end complete rather than fully comprehensive.'::text
            ELSE NULL::text
        END,
        CASE
            WHEN v.player_source_status = 'general'::text THEN 'Uses a general official source page rather than an exact shareable view.'::text
            ELSE NULL::text
        END], NULL::text) AS v16_2_warnings,
    c.measurement_type,
    c.eligible_universe_type,
    c.eligible_universe_rule,
    c.eligible_country_count,
    c.eligible_country_iso3,
    c.coverage_within_eligible_universe,
    c.excluded_country_reason,
    legacy.blockers AS legacy_rejection_blockers_v16_2_6
   FROM category_runtime_review_v16 v
     JOIN category_promotion_assessment_v16_2 a ON a.category_id = v.id
     JOIN stat_categories c ON c.id = v.id
     CROSS JOIN LATERAL ( SELECT category_legacy_rejection_blockers_v16_2_6(c.id, v.effective_title) AS blockers) legacy;

insert into public.generator_reachability_v16_2_7(category_id,difficulty,reachable,failure_stage,detail,audit_version,checked_at)
select e.category_id,p->>'difficulty',true,null,
jsonb_build_object('witness',p->'witness','snapshotFingerprint',e.snapshot_fingerprint,'rulesVersion',e.rules_version,'auditFingerprint',p->>'fingerprint')::text,
'geostats-v16.3.4-production-solver-v1',now()
from public.category_recovery_evidence_v16_3_4 e cross join lateral jsonb_array_elements(e.proofs) p
on conflict(category_id,difficulty) do update set reachable=true,failure_stage=null,detail=excluded.detail,audit_version=excluded.audit_version,checked_at=excluded.checked_at;

select public.refresh_v16_2_runtime_catalog();

do $accept$
declare problems jsonb;
begin
 if exists(select 1 from recovery_baseline b left join public.category_runtime_review_v16_2 v on v.id=b.id where not coalesce(v.computed_playable_v16_2,false))
 then raise exception 'Recovery would remove an existing playable category'; end if;
 select jsonb_agg(jsonb_build_object('id',v.id,'blockers',v.v16_2_blockers,'status',v.editorial_status,
 'proofCurrent',public.category_recovery_ready_v16_3_4(v.id),'semantic',v.semantic_audit_issues,'quality',v.quality_score,
 'credibility',v.credibility_score)) into problems
 from recovery_proposals p join public.category_runtime_review_v16_2 v on v.id=p.id
 where not v.computed_playable_v16_2 or not v.enabled or not v.eligible_daily;
 if problems is not null then raise exception 'Recovery acceptance failed: %',problems; end if;
 if (select count(*) from public.category_runtime_review_v16_2 where computed_playable_v16_2)<>406
 then raise exception 'Unexpected catalog growth outside 21 reviewed candidates'; end if;
 perform public.assert_v16_3_4_runtime_catalog();
end $accept$;
commit;

